 if(Math.random()>chance)return 0;
 const choices=G.households.filter(h=>h.home>=0&&h.people.length>0&&h.stress>42&&h.cash<Math.max(550,h.people.length*260))
  .sort((a,b)=>(b.stress-a.stress)+(a.cash-b.cash)*.005);
