const spriteCache=new Map();let displayItems=[];
// Original, hand-drawn miniature pixel-art tileset. Pixel edges remain sharp
// at every camera scale. Images are loaded lazily and retained across seasons.
const pictureCache=new Map();
function paintedSprite(item){
 const season=G.month>=10?2:G.month>=7?1:0;
 const label=item.kind==='tree'?`tree-${season}-${item.id%8}`:
 `${item.b.kind}-${item.b.kind==='home'?item.b.id%16:['grocer','bakery','tavern','office','factory','warehouse','apartment'].includes(item.b.kind)?item.b.id%3:0}`;
 if(!pictureCache.has(label)){
  const im=new Image();pictureCache.set(label,im);
  im.onload=()=>{dirty=true};im.onerror=()=>{pictureCache.set(label,null)};
  im.src=ART_DATA[label]||'art/'+label+'.png';
 }
 const im=pictureCache.get(label);
 return im&&im.complete&&im.naturalWidth>0?im:null;
}

