 for(let y=0;y<T;y++)for(let x=0;x<T;x++)if(G.tiles[roadId(x,y)]===3&&!occupied.has(roadId(x,y))){if(((roadId(x,y)*31+(G.worldSeed||0))%7)<2)continue;const point=iso(x,y);displayItems.push({kind:'tree',id:roadId(x,y),x:point[0],y:point[1]+TH/2})}
