window.__townTest={inbox:()=>G.councilInbox||[],offerPetition:()=>offerCouncilEvent(),reviewPetition:reviewCouncilInbox,finance:()=>({banks:G.banks,loans:G.loans,indicators:G.finance,deposits:G.banks.map(b=>bankDeposits(b.id))}),takeLoan:(kind,id,amount,term)=>bankLoan(kind,id,amount,term),bankFailure:(id)=>liquidateBank(G.banks[id],'Test insolvency'),reverseLand:()=>reverseRedevelopment(),renderBench:(n=100)=>{let t=performance.now();for(let i=0;i<n;i++){dirty=true;draw()}return Math.round((performance.now()-t)/n*100)/100},advanceTraffic:(dt=1)=>{trafficUpdate(dt);return traffic.length},traffic:()=>traffic.map(v=>({id:v.id,route:v.path,position:vehiclePosition(v),segment:v.segment,fraction:v.fraction,wait:v.wait,age:v.age})),road:()=>roadMetrics(),regional:()=>({landUse:G?.landUse,fieldCount:G?.fieldCount,airport:G?.airport,demand:cityDemand(),startFields:()=>farmDistrictExpansion(cityDemand()),startRedevelopment:()=>urbanRedevelopment(cityDemand()),startAirfield:()=>airfieldInvestment(cityDemand()),airfieldCandidate:()=>airfieldCandidate(),firmTypes:G?.firms.reduce((t,f)=>(t[f.kind]=(t[f.kind]||0)+Number(!f.closed),t),{})}),development:()=>({development:G?.development,metro:G?.metro,privateRoads:G?.privateRoads}),autogrow:()=>autonomousDevelopment(),path:(a,b)=>routeBetween(a,b),spawn:()=>beginVehicle(),invalidateRoads:()=>invalidateRoads(),get:()=>({day:G?.day,treasury:G?.treasury,debt:G?.debt,population:G?.stats.population,employment:G?.stats.employment,hardship:G?.stats.hardship,businesses:G?.stats.businesses,approval:G?.council.approval,cases:G?.cases.length,total:G?totalMoney():0,regional:G?.region,hhCash:G?.households.reduce((n,h)=>n+h.cash,0),firmCash:G?.firms.reduce((n,f)=>n+f.cash,0),events:G?.events.length,policy:G?.policy,stats:G?.stats,achievements:G?.achievements,pending:!!pendingEvent}),
 step:(n=1)=>{for(let i=0;i<n;i++){if(pendingEvent){const ix=pendingEvent.choices.findIndex(c=>!c.cost||G.treasury>=c.cost);$('eventChoices').querySelectorAll('button')[Math.max(0,ix)]?.click()}tick()}return G.stats},
 save:()=>JSON.stringify(G),load:(t)=>hydrateSave(t),choose:(i)=>{$('eventChoices').querySelectorAll('button')[i]?.click()},
 reset:(sc='settlement')=>{chosenScenario=sc;seed();invalidateRoads();return G.stats},set:(k,v)=>{G.policy[k]=v;recompute()}};
